import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"AIHubMix","description":"AIHubMix 무료 모델 게이트웨이 — 공식 입구, *-free 텍스트·이미지, Key 받기, MiniTavern 입력법.","frontmatter":{"title":"AIHubMix","description":"AIHubMix 무료 모델 게이트웨이 — 공식 입구, *-free 텍스트·이미지, Key 받기, MiniTavern 입력법.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"AIHubMix · MiniTavern Docs"}],["meta",{"property":"og:description","content":"AIHubMix 무료 모델 게이트웨이 — 공식 입구, *-free 텍스트·이미지, Key 받기, MiniTavern 입력법."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/free-cloud/aihubmix"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/free-cloud/aihubmix"}]]},"headers":[],"relativePath":"ko/free-cloud/aihubmix.md","filePath":"ko/free-cloud/aihubmix.md","lastUpdated":1787224147000}'),d={name:"ko/free-cloud/aihubmix.md"};function i(n,e,l,h,c,s){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="aihubmix" tabindex="-1">AIHubMix <a class="header-anchor" href="#aihubmix" aria-label="Permalink to &quot;AIHubMix&quot;">​</a></h1><p>통합 <strong>OpenAI 호환</strong> API 게이트웨이. <strong>27+개 <code>-free</code> 접미 모델</strong>을 플랫폼 보조금으로 모델별 한도 내 무료（카드 불필요）. Key 하나로 GPT / Gemini / GLM / Kimi 비교·무료 이미지에 적합. 소개: <a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">AIHubMix 무료 AI 모델</a>.</p><blockquote><p>한도·목록·「신규 증정」은 변합니다. <strong><a href="https://aihubmix.com/models" target="_blank" rel="noreferrer">aihubmix.com/models</a>와 콘솔 기준</strong>.</p></blockquote><h2 id="공식과-입구" tabindex="-1">공식과 입구 <a class="header-anchor" href="#공식과-입구" aria-label="Permalink to &quot;공식과 입구&quot;">​</a></h2><table tabindex="0"><thead><tr><th>자원</th><th>주소</th></tr></thead><tbody><tr><td>공식 / 가입</td><td><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a></td></tr><tr><td>무료 모델 설명</td><td><a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">docs.aihubmix.com/cn/blogs/free-ai-models</a></td></tr><tr><td>모델 광장</td><td><a href="https://aihubmix.com/models" target="_blank" rel="noreferrer">aihubmix.com/models</a></td></tr><tr><td>개발자 문서</td><td><a href="https://docs.aihubmix.com/cn" target="_blank" rel="noreferrer">docs.aihubmix.com/cn</a></td></tr><tr><td>API Base URL</td><td><code>https://aihubmix.com/v1</code></td></tr></tbody></table><h2 id="무료-받기" tabindex="-1">무료 받기 <a class="header-anchor" href="#무료-받기" aria-label="Permalink to &quot;무료 받기&quot;">​</a></h2><ol><li><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a> 이메일 또는 OAuth（공식: <strong>카드 불필요</strong>）.</li><li><strong>API Keys</strong> → Key 생성（형식 <code>sk-…</code>）.</li><li>광장에서 무료 모델 필터, ID 기록（보통 <code>-free</code> 끝）.</li><li>MiniTavern <strong>Custom (OpenAI)</strong> / **Custom (OpenAI Images)**에 Base URL·Key.</li></ol><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>무료</td><td>ID에 <code>-free</code>; <strong>RPM / 일 token</strong> 등, 일일 리셋（모델 페이지）</td></tr><tr><td>신규</td><td>등록 후 일부 무료 모델에 제한 횟수 증정（GPT-5.5, GPT-Image-2 등）; 충전으로 더 — 콘솔 기준</td></tr><tr><td>카드</td><td>무료는 보통 불필요</td></tr><tr><td>OpenRouter와</td><td>OpenRouter는 OSS 넓이; AIHubMix는 보조금 프론티어 클로즈드 <code>*-free</code>（GPT / Gemini 미러 등）</td></tr></tbody></table><h2 id="모델-목록" tabindex="-1">모델 목록 <a class="header-anchor" href="#모델-목록" aria-label="Permalink to &quot;모델 목록&quot;">​</a></h2><p>공식 무료 모델 글（약 2026-05）발췌; <strong>실제는 광장 기준</strong>. ID <strong>대소문자 구분</strong>.</p><h3 id="텍스트-대화-추론" tabindex="-1">텍스트（대화 / 추론） <a class="header-anchor" href="#텍스트-대화-추론" aria-label="Permalink to &quot;텍스트（대화 / 추론）&quot;">​</a></h3><p>Chat Completions. MiniTavern: <strong>Custom (OpenAI)</strong>.</p><h4 id="일반-대화" tabindex="-1">일반 대화 <a class="header-anchor" href="#일반-대화" aria-label="Permalink to &quot;일반 대화&quot;">​</a></h4><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>gpt-5.5-free</code></td><td>플래그십 대화 / Agent / 코드（보조금）</td></tr><tr><td><code>gpt-4o-free</code></td><td>멀티모달 비전</td></tr><tr><td><code>gpt-4.1-free</code></td><td>긴 컨텍스트（약 1M）</td></tr><tr><td><code>gpt-4.1-mini-free</code> / <code>gpt-4.1-nano-free</code></td><td>속도·비용</td></tr><tr><td><code>gemini-3-flash-preview-free</code></td><td>초장 컨텍스트, 멀티모달</td></tr><tr><td><code>glm-4.7-flash-free</code></td><td>Zhipu Flash</td></tr><tr><td><code>mimo-v2-flash-free</code> / <code>ling-2.6-flash-free</code></td><td>저지연 대화</td></tr></tbody></table><h4 id="코딩" tabindex="-1">코딩 <a class="header-anchor" href="#코딩" aria-label="Permalink to &quot;코딩&quot;">​</a></h4><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>coding-glm-5.1-free</code></td><td>공식 추천 무료 코딩</td></tr><tr><td><code>coding-glm-5-free</code> / <code>coding-glm-5-turbo-free</code> / <code>coding-glm-4.7-free</code> 등</td><td>GLM 코딩</td></tr><tr><td><code>kimi-for-coding-free</code> / <code>k2.6-code-preview-free</code></td><td>Kimi 코딩</td></tr><tr><td><code>coding-minimax-m2-free</code> … <code>coding-minimax-m2.7-free</code></td><td>MiniMax 코딩</td></tr><tr><td><code>step-3.5-flash-free</code></td><td>경량 완성</td></tr></tbody></table><h4 id="agent-추론" tabindex="-1">Agent / 추론 <a class="header-anchor" href="#agent-추론" aria-label="Permalink to &quot;Agent / 추론&quot;">​</a></h4><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>xiaomi-mimo-v2-pro-free</code></td><td>도구 / Agent</td></tr><tr><td><code>xiaomi-mimo-v2.5-free</code></td><td>더 긴 컨텍스트·다중 도구</td></tr></tbody></table><p>롤플레이는 <code>gpt-4o-free</code>, <code>gemini-3-flash-preview-free</code>, <code>glm-4.7-flash-free</code>부터; 코딩 모델은 장편에 부적합할 수 있음.</p><h3 id="이미지-문생도-편집" tabindex="-1">이미지（문생도 / 편집） <a class="header-anchor" href="#이미지-문생도-편집" aria-label="Permalink to &quot;이미지（문생도 / 편집）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>모델 ID</th><th>인터페이스</th><th>App</th></tr></thead><tbody><tr><td><code>gpt-image-2-free</code></td><td><code>POST /v1/images/generations</code>（edits도）</td><td><strong>Custom (OpenAI Images)</strong></td></tr><tr><td><code>gemini-3.1-flash-image-preview-free</code>（Nano Banana 2）</td><td>Chat Completions 대화 생성 가능</td><td>이미지 연결 호환 불확실; Images 또는 <code>gpt-image-2-free</code></td></tr></tbody></table><h3 id="비디오" tabindex="-1">비디오 <a class="header-anchor" href="#비디오" aria-label="Permalink to &quot;비디오&quot;">​</a></h3><p>무료 목록은 <strong>LLM + 이미지</strong> 중심; 비디오는 광장 표기 기준. MiniTavern <strong>내장 비디오 없음</strong>.</p><h2 id="minitavern-입력" tabindex="-1">MiniTavern 입력 <a class="header-anchor" href="#minitavern-입력" aria-label="Permalink to &quot;MiniTavern 입력&quot;">​</a></h2><p>일반: <a href="/ultra_guides/ko/manual/model-link">모델 연결</a>.</p><h3 id="채팅" tabindex="-1">채팅 <a class="header-anchor" href="#채팅" aria-label="Permalink to &quot;채팅&quot;">​</a></h3><p>경로: <strong>설정 → 모델 → 모델 연결 → 새로 만들기</strong></p><ol><li><strong>Custom (OpenAI)</strong></li><li>Base URL: <code>https://aihubmix.com/v1</code></li><li>API Key</li><li>모델 <code>gpt-4o-free</code> 또는 광장 <code>*-free</code></li><li><strong>테스트</strong> → 기본값</li></ol><h3 id="이미지" tabindex="-1">이미지 <a class="header-anchor" href="#이미지" aria-label="Permalink to &quot;이미지&quot;">​</a></h3><p>경로: <strong>설정 → 이미지 생성 → 이미지 연결</strong></p><ol><li><strong>Custom (OpenAI Images)</strong></li><li>Base URL 동일</li><li>같은 Key; <code>gpt-image-2-free</code></li><li>테스트 후 <code>/imagine</code> 등</li></ol><h2 id="관련-장" tabindex="-1">관련 장 <a class="header-anchor" href="#관련-장" aria-label="Permalink to &quot;관련 장&quot;">​</a></h2><ul><li><a href="/ultra_guides/ko/free-cloud/">무료 클라우드 개요</a></li><li><a href="/ultra_guides/ko/free-cloud/#무료-이미지-생성">무료 이미지</a></li><li><a href="/ultra_guides/ko/free-cloud/opencode-zen">OpenCode Zen</a> — 코딩 게이트웨이·다른 Free 텍스트</li><li><a href="/ultra_guides/ko/free-cloud/agnes-ai">Agnes AI</a></li><li><a href="/ultra_guides/ko/free-cloud/openrouter">OpenRouter</a> — OSS <code>:free</code> 풀</li><li><a href="/ultra_guides/ko/manual/model-link">모델 연결</a></li></ul>',33)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
